using System.Text.RegularExpressions;

namespace MyApp.Evaluation;

/// <summary>
/// Represents a single evaluation scenario loaded from evaluation.yml.
/// </summary>
public class EvaluationScenario
{
    public string Id { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<EvaluationStep> Steps { get; set; } = [];

    public override string ToString() => Id;

    /// <summary>
    /// Loads scenarios from the YAML evaluation file using a minimal parser.
    /// </summary>
    public static List<EvaluationScenario> LoadFromYaml(string path)
    {
        var scenarios = new List<EvaluationScenario>();
        var lines = File.ReadAllLines(path);

        EvaluationScenario? current = null;

        foreach (var line in lines)
        {
            var trimmed = line.TrimStart();

            if (trimmed.StartsWith("- id:"))
            {
                current = new EvaluationScenario { Id = trimmed["- id:".Length..].Trim() };
                scenarios.Add(current);
            }
            else if (trimmed.StartsWith("description:") && current is not null && string.IsNullOrEmpty(current.Description))
            {
                current.Description = trimmed["description:".Length..].Trim();
            }
        }

        return scenarios;
    }
}

public class EvaluationStep
{
    public string Action { get; set; } = string.Empty;
    public string? Input { get; set; }
    public Dictionary<string, object> Expect { get; set; } = [];
}

